INSERT INTO "feed_items"("project_id","item_id","source_id","signal_id","signal_revision","kind","title","summary","body","source_kind","source_label","external_id","url","origin_status","priority","tags_json","author","disposition","read_at","revision","source_created_at","source_updated_at","imported_at","updated_at") VALUES('molis-work-v1-demo','feeditem-4e0c70c9-6442-416b-996d-d361e7ea9d90','feed-source-f34498b13c742f0d0f851765e48fe4d6',NULL,NULL,'rss_entry','第一次把模糊想法收成目标树','用户要能从列表看出下一步、阻塞和完成依据。','长程任务最容易在换对话后丢失共同进度。先把模糊想法收成目标树，再决定谁做下一步。这篇文章和当前示例项目的主 Goal 直接相关。','rss','Solidot','https://example.com/posts/goal-tree-first-run','https://www.solidot.org/','inbox','medium','["RSS","产品设计"]','Solidot','inbox',NULL,1,'2026-09-16T04:25:00.000Z','2026-09-16T04:25:00.000Z','2026-01-15T09:00:00.000Z','2026-01-15T09:00:00.000Z');
INSERT INTO "feed_items"("project_id","item_id","source_id","signal_id","signal_revision","kind","title","summary","body","source_kind","source_label","external_id","url","origin_status","priority","tags_json","author","disposition","read_at","revision","source_created_at","source_updated_at","imported_at","updated_at") VALUES('molis-work-v1-demo','feeditem-5d6d5eec-da0d-483c-8fe7-dedbbb3667d4','demo-github',NULL,NULL,'github_notification','PR #418 请确认完成依据是否写进事件记录','Review 要求核对：工作何时开始、提交了什么、为什么可以算完成。','请对照 CORE 的约定：从约定、报告到收尾要形成完整记录。这条通知需要人决定是否并入当前 Goal。','github','GitHub · molis-work','demo-github-pr-418','https://github.com/example/molis-work/pull/418','inbox','medium','["GitHub","Review"]','octocat','inbox',NULL,1,'2026-09-16T06:18:00.000Z','2026-09-16T06:18:00.000Z','2026-01-15T09:00:00.000Z','2026-01-15T09:00:00.000Z');
INSERT INTO "feed_items"("project_id","item_id","source_id","signal_id","signal_revision","kind","title","summary","body","source_kind","source_label","external_id","url","origin_status","priority","tags_json","author","disposition","read_at","revision","source_created_at","source_updated_at","imported_at","updated_at") VALUES('molis-work-v1-demo','feeditem-b2ec246a-b9bf-4863-9da1-08d019ab9cf6','feed-source-5496d064f90938a458c4b1eec79d4a4b',NULL,NULL,'web_query_result','不同 Runtime 怎样读同一份项目进度','查询「AI 工作台如何保存共同进度」的本地示例结果。','如果每个入口各自记状态，换一次对话就要重新解释整个项目。共同底座应保存 Goal、关系、决定和完成依据。','web_query','共同进度怎么被记住','query:shared-progress-1',NULL,'inbox','medium','["网页查询"]',NULL,'inbox',NULL,1,'2026-09-15T10:00:00.000Z','2026-09-15T10:00:00.000Z','2026-01-15T09:00:00.000Z','2026-01-15T09:00:00.000Z');
